static void *rg_pool_wrap(void *target) {
    if (!target) return NULL;
    int n = __atomic_load_n(&rg_pool_used, __ATOMIC_ACQUIRE);
    for (int k = 0; k < n; k++)
        if (rg_pool_target[k] == target) return rg_pool_fns[k];
    int k = __atomic_fetch_add(&rg_pool_used, 1, __ATOMIC_ACQ_REL);
    if (k >= RG_POOL) {
        if (!__atomic_exchange_n(&rg_logged, 1, __ATOMIC_ACQ_REL)) fprintf(stderr, "rg-stackalign: voorraad op; verdere functies zonder uitlijning\n");
        return target;
    }
    rg_pool_target[k] = target;
    return rg_pool_fns[k];
}

